```python
def merge_dicts(left_dict, right_dict):
    """Merge two dictionaries and return the merged dictionary"""

    # Check if left or right dict has no keys
    if not all(key in left_dict for key in left_dict):
        return {}
    if not all(key in right_dict for key in right_dict):
        return left_dict

    merged_dict = {}
    for key, value in left_dict.items():
        if key in right_dict:
            merged_dict[key] = value + right_dict[key]
        else:
            merged_dict[key] = value

    return merged_dict
