   # Iterate through the range of integers from 2 to n starting at index 0
   for I in range(3, int(math.sqrt(n)) + 1):
       if not all([prime % i == 0 for prime in primes[i*i:]]):
           # If any non-prime divisors are found, set the corresponding boolean value to False and update the array accordingly
           primes[(i+1)*(i+1)-2*(n - I**2) + n] = False

