def count_vowel(string):
    """
    This function takes a string as input and returns a dictionary with counts of each vowel (a, e, i, o, u) present.

    Args:
        string (str): The string to be counted.

    Returns:
        dict: A dictionary with counts of each vowel (a, e, i, o, u) present.
    """

    # Create a dictionary to store the counts
    count_dict = {}

    # Loop through each character in the string
    for char in string:
