def is_prime(n):
    # Check if n is zero or negative
    if n < 0:
        raise ValueError("Negative input")

    # Check if n is equal to 1 (or 2)
    if n == 1 or n == 2:
        return True

    # If n is not divisible by any integer less than or equal to it, it's prime
    for I in range(3, int(n**0.5)+1, 2):
        if n % I == 0:
            return False

    return True
